// Goocommerce PDF Invoices & Packing Slips (like WooCommerce PDF Invoices & Packing Slips): invoices
// with a sequential number (prefix, suffix, padding; the counter in goo_pdf_counters is incremented
// atomically) and packing slips, generated by the pure-Go writer in goo_ext_pdf_writer.go. Documents
// are created from the order screen's actions, downloaded from Goocommerce › PDF documents (one order
// or several in one PDF), attached to the chosen e-mails, and customers download their invoice from
// /?goo-pdf=invoice&order_id=<id>&key=<order key> (s.gooInvoiceLink, linked on the thank-you page).

const (
	gooPDFKey   = "pdf_invoices"
	gooPDFNonce = "goo-pdf-documents"
)

var gooPDFEmailOpts = []gooOpt{
	{"new_order", "New order (admin)"}, {"cancelled_order", "Cancelled order (admin)"}, {"failed_order", "Failed order (admin)"},
	{"customer_on_hold_order", "Order on-hold"}, {"customer_processing_order", "Processing order"}, {"customer_completed_order", "Completed order"},
	{"customer_refunded_order", "Refunded order"}, {"customer_invoice", "Customer invoice / Order details"}, {"customer_note", "Customer note"},
}

func init() {
	gooRegisterExtension(&gooExtension{
		Key:         gooPDFKey,
		Name:        "PDF Invoices & Packing Slips",
		Description: "Create PDF invoices with sequential numbers and packing slips, attach invoices to order e-mails and let customers download them.",
		Icon:        "dashicons-media-document",
		Category:    "Store management",
		Fields: []gooField{
			{ID: "shop", Title: "Shop details", Type: "title", Desc: "Printed on the top of your documents."},
			{ID: "shop_name", Title: "Shop name", Type: "text", Default: "", Desc: "Leave empty to use the site title."},
			{ID: "shop_address", Title: "Shop address", Type: "textarea", Default: ""},
			{ID: "logo_url", Title: "Shop header / logo", Type: "text", Default: "", Holder: "https://…/wp-content/uploads/…/logo.jpg",
				Desc: "The URL of an image in your Media Library (or its attachment ID). JPEG, PNG or GIF."},
			{ID: "footer", Title: "Footer", Type: "textarea", Default: "", Desc: "Terms, conditions or policies printed at the bottom of each page."},
			{ID: "paper_size", Title: "Paper size", Type: "select", Default: "a4", Options: []gooOpt{{"a4", "A4"}, {"letter", "Letter"}}},
			{ID: "shop_end", Type: "sectionend"},
			{ID: "invoice", Title: "Invoice", Type: "title"},
			{ID: "number_prefix", Title: "Number prefix", Type: "text", Default: "", Desc: "Placeholders: <code>[invoice_year]</code>, <code>[invoice_month]</code>, <code>[order_year]</code>, <code>[order_month]</code>, <code>[order_number]</code>."},
			{ID: "number_suffix", Title: "Number suffix", Type: "text", Default: ""},
			{ID: "number_padding", Title: "Number padding", Type: "number", Default: float64(0), Min: "0", Step: "1", Desc: "Pad the number with zeros to this many digits (5 → 00042)."},
			{ID: "next_number", Title: "Next invoice number", Type: "number", Default: float64(1), Min: "1", Step: "1",
				Desc: "The number of the next invoice. Changing it resets the counter (without prefix, suffix or padding)."},
			{ID: "display_shipping_address", Title: "Shipping address", Type: "checkbox", Default: true, Desc: "Display the shipping address on invoices"},
			{ID: "display_email", Title: "Email address", Type: "checkbox", Default: true, Desc: "Display the customer's email address"},
			{ID: "display_phone", Title: "Phone number", Type: "checkbox", Default: true, Desc: "Display the customer's phone number"},
			{ID: "attach_to", Title: "Attach to", Type: "multiselect", Default: []any{"customer_completed_order", "customer_invoice"}, Options: gooPDFEmailOpts,
				Desc: "The e-mails the invoice is attached to."},
			{ID: "disable_free", Title: "Disable for free orders", Type: "checkbox", Default: false, Desc: "Do not create invoices for orders with a total of 0"},
			{ID: "my_account_access", Title: "Allow customers to download", Type: "select", Default: "always",
				Options: []gooOpt{{"always", "Always"}, {"available", "Only when an invoice has already been created"}, {"never", "Never"}}},
			{ID: "mark_printed", Title: "Mark as printed", Type: "select", Default: "",
				Options: []gooOpt{{"", "Never"}, {"download", "When downloaded from the admin"}, {"email", "When attached to an e-mail"}, {"always", "When downloaded or attached"}},
				Desc:    "Store the time an invoice was first printed in the order (_wcpdf_invoice_printed_on)."},
			{ID: "invoice_end", Type: "sectionend"},
		},
		Pages: []gooExtMenuItem{{Page: "pdf-documents", Title: "PDF documents"}},
	})
	gooExtAdminPages["pdf-documents"] = func(s *Server, c *gin.Context) { s.gooPDFAdmin(c) }
	gooOrderActions = append(gooOrderActions,
		&gooOrderAction{ID: "goo_pdf_invoice", Label: "Create PDF invoice", Module: gooPDFKey, Run: func(s *Server, c *gin.Context, o *gooOrder) error {
			if !s.gooExtOn(gooPDFKey) {
				return nil
			}
			num, err := s.gooPDFInvoiceNumber(c.Request.Context(), o)
			if err != nil {
				return err
			}
			_ = s.gooAddOrderNote(c.Request.Context(), o, "PDF invoice "+num+" created.", false, "")
			return nil
		}},
		&gooOrderAction{ID: "goo_pdf_packing_slip", Label: "Create PDF packing slip", Module: gooPDFKey, Run: func(s *Server, c *gin.Context, o *gooOrder) error {
			if !s.gooExtOn(gooPDFKey) {
				return nil
			}
			if o.MetaString("_wcpdf_packing_slip_date") == "" {
				return s.gooPDFSetMeta(c.Request.Context(), o, map[string]any{"_wcpdf_packing_slip_date": time.Now().UTC().Format(time.RFC3339)})
			}
			return nil
		}},
	)
	gooEmailAttachHooks = append(gooEmailAttachHooks, gooPDFEmailAttach)
	gooFrontRoutes = append(gooFrontRoutes, gooPDFRoute)
	gooOnPage("thankyou", gooPDFThankYou)
}

// Numbers -----------------------------------------------------------------------------------------------

// gooPDFSetMeta merges meta into an order without rewriting the rest of the row.
func (s *Server) gooPDFSetMeta(ctx context.Context, o *gooOrder, meta map[string]any) error {
	raw, _ := json.Marshal(meta)
	if _, err := s.store.Pool.Exec(ctx, `UPDATE goo_orders SET meta = meta || $2::jsonb WHERE id = $1`, o.ID, raw); err != nil {
		return err
	}
	if o.Meta == nil {
		o.Meta = map[string]any{}
	}
	for k, v := range meta {
		o.Meta[k] = v
	}
	return nil
}

// gooPDFFree reports whether invoices are disabled for this (free) order.
func (s *Server) gooPDFFree(o *gooOrder) bool {
	return s.gooExtBool(gooPDFKey, "disable_free") && math.Abs(o.Total) < 0.005
}

// gooPDFInvoiceNumber returns the order's invoice number, creating it on first use: the counter row is
// locked and incremented in the same transaction that writes the number into the order (FOR UPDATE on
// the order), so concurrent requests never share or skip a number.
func (s *Server) gooPDFInvoiceNumber(ctx context.Context, o *gooOrder) (string, error) {
	if n := o.MetaString("_wcpdf_invoice_number"); n != "" {
		return n, nil
	}
	if s.gooPDFFree(o) {
		return "", errors.New("Invoices are disabled for free orders.")
	}
	start := int64(s.gooExtInt(gooPDFKey, "next_number"))
	if start < 1 {
		start = 1
	}
	now := time.Now()
	var formatted string
	var meta map[string]any
	err := pgx.BeginFunc(ctx, s.store.Pool, func(tx pgx.Tx) error {
		var raw []byte
		if err := tx.QueryRow(ctx, `SELECT meta FROM goo_orders WHERE id = $1 FOR UPDATE`, o.ID).Scan(&raw); err != nil {
			return err
		}
		have := map[string]any{}
		_ = json.Unmarshal(raw, &have)
		if n, ok := have["_wcpdf_invoice_number"].(string); ok && n != "" {
			formatted, meta = n, have
			return nil
		}
		var num int64
		if err := tx.QueryRow(ctx, `INSERT INTO goo_pdf_counters (name, next, applied) VALUES ('invoice', $1::bigint + 1, $1::bigint)
			ON CONFLICT (name) DO UPDATE SET next = CASE WHEN goo_pdf_counters.applied <> $1::bigint THEN $1::bigint ELSE goo_pdf_counters.next END + 1,
			applied = $1::bigint RETURNING next - 1`, start).Scan(&num); err != nil {
			return err
		}
		formatted = s.gooPDFFormatNumber(num, o, now)
		meta = map[string]any{
			"_wcpdf_invoice_number": formatted,
			"_wcpdf_invoice_number_data": map[string]any{"number": float64(num), "formatted_number": formatted, "prefix": s.gooExtString(gooPDFKey, "number_prefix"),
				"suffix": s.gooExtString(gooPDFKey, "number_suffix"), "padding": float64(s.gooExtInt(gooPDFKey, "number_padding"))},
			"_wcpdf_invoice_date": now.UTC().Format(time.RFC3339),
		}
		b, _ := json.Marshal(meta)
		_, err := tx.Exec(ctx, `UPDATE goo_orders SET meta = meta || $2::jsonb WHERE id = $1`, o.ID, b)
		return err
	})
	if err != nil {
		return "", err
	}
	if o.Meta == nil {
		o.Meta = map[string]any{}
	}
	for k, v := range meta {
		if strings.HasPrefix(k, "_wcpdf_") {
			o.Meta[k] = v
		}
	}
	return formatted, nil
}

// gooPDFFormatNumber applies prefix, padding and suffix with their placeholders.
func (s *Server) gooPDFFormatNumber(n int64, o *gooOrder, invoiceDate time.Time) string {
	digits := strconv.FormatInt(n, 10)
	if pad := s.gooExtInt(gooPDFKey, "number_padding"); pad > len(digits) && pad < 20 {
		digits = strings.Repeat("0", pad-len(digits)) + digits
	}
	r := strings.NewReplacer("[invoice_year]", invoiceDate.Format("2006"), "[invoice_month]", invoiceDate.Format("01"),
		"[order_year]", o.DateCreated.Format("2006"), "[order_month]", o.DateCreated.Format("01"), "[order_number]", o.Number())
	return r.Replace(s.gooExtString(gooPDFKey, "number_prefix")) + digits + r.Replace(s.gooExtString(gooPDFKey, "number_suffix"))
}

// gooPDFInvoiceDate is the invoice's date (now when it has none).
func gooPDFInvoiceDate(o *gooOrder) time.Time {
	if t, err := time.Parse(time.RFC3339, o.MetaString("_wcpdf_invoice_date")); err == nil {
		return t
	}
	return time.Now()
}

// gooPDFMarkPrinted stores the first print time when the setting asks for it on this event.
func (s *Server) gooPDFMarkPrinted(ctx context.Context, o *gooOrder, event string) {
	mode := s.gooExtString(gooPDFKey, "mark_printed")
	if mode == "" || (mode != "always" && mode != event) || o.MetaString("_wcpdf_invoice_printed_on") != "" {
		return
	}
	_ = s.gooPDFSetMeta(ctx, o, map[string]any{"_wcpdf_invoice_printed_on": time.Now().UTC().Format(time.RFC3339), "_wcpdf_invoice_printed_via": event})
}

// Rendering ------------------------------------------------------------------------------------------------

// gooPDFRender renders one document per order ("invoice" or "packing-slip") into a single PDF;
// invoices get their number first.
func (s *Server) gooPDFRender(ctx context.Context, doc string, orders []*gooOrder) ([]byte, error) {
	w, h := gooPDFA4W, gooPDFA4H
	if s.gooExtString(gooPDFKey, "paper_size") == "letter" {
		w, h = gooPDFLetterW, gooPDFLetterH
	}
	p := newGooPDF(w, h)
	logo := -1
	if data := s.gooPDFLogo(ctx); data != nil {
		if i, err := p.AddJPEG(data); err == nil {
			logo = i
		}
	}
	var titles []string
	for _, o := range orders {
		if doc == "invoice" {
			num, err := s.gooPDFInvoiceNumber(ctx, o)
			if err != nil {
				if len(orders) == 1 {
					return nil, err
				}
				continue
			}
			titles = append(titles, "Invoice "+num)
		} else {
			titles = append(titles, "Packing slip "+o.Number())
		}
		s.gooPDFDocument(ctx, p, doc, o, logo)
	}
	if p.PageCount() == 0 {
		return nil, errors.New("No documents to create.")
	}
	p.Title = strings.Join(titles, ", ")
	return p.Bytes(), nil
}

// gooPDFLogo reads the logo image from the uploads directory (an uploads URL or an attachment ID).
func (s *Server) gooPDFLogo(ctx context.Context) []byte {
	v := strings.TrimSpace(s.gooExtString(gooPDFKey, "logo_url"))
	if v == "" || s.cfg.UploadsDir == "" {
		return nil
	}
	rel := ""
	if id, err := strconv.ParseInt(v, 10, 64); err == nil {
		if a, err := s.store.GetAttachment(ctx, id); err == nil {
			rel = a.FilePath
		}
	} else if i := strings.Index(v, "/wp-content/uploads/"); i >= 0 {
		rel = v[i+len("/wp-content/uploads/"):]
		if j := strings.IndexAny(rel, "?#"); j >= 0 {
			rel = rel[:j]
		}
		if u, err := url.PathUnescape(rel); err == nil {
			rel = u
		}
	}
	if rel == "" {
		return nil
	}
	root, err := filepath.Abs(s.cfg.UploadsDir)
	if err != nil {
		return nil
	}
	full := filepath.Join(root, filepath.FromSlash(filepath.Clean("/"+rel)))
	if !strings.HasPrefix(full, root+string(filepath.Separator)) {
		return nil
	}
	data, err := os.ReadFile(full)
	if err != nil || len(data) > 8<<20 {
		return nil
	}
	return data
}

// gooPDFAddress formats an address in lines (WC's address formats, simplified to the common order).
func gooPDFAddress(a map[string]string) []string {
	var lines []string
	add := func(v string) {
		if v = strings.TrimSpace(v); v != "" {
			lines = append(lines, v)
		}
	}
	add(strings.TrimSpace(a["first_name"] + " " + a["last_name"]))
	add(a["company"])
	add(a["address_1"])
	add(a["address_2"])
	city := strings.TrimSpace(strings.Join(strings.Fields(a["city"]+" "+gooStateName(a["country"], a["state"])+" "+a["postcode"]), " "))
	add(city)
	if a["country"] != "" {
		add(gooCountryName(a["country"]))
	}
	return lines
}

// gooPDFDocument draws one order's invoice or packing slip on new pages.
func (s *Server) gooPDFDocument(ctx context.Context, p *gooPDF, doc string, o *gooOrder, logo int) {
	const margin = 42.0
	right := p.W - margin
	firstPage := p.PageCount()
	p.AddPage()
	p.SetGray(0)
	invoice := doc == "invoice"
	cur := o.Currency
	money := func(v float64) string { return s.gooPricePlain(v, cur) }
	shopName := defaultStr(strings.TrimSpace(s.gooExtString(gooPDFKey, "shop_name")), s.settings.String("blogname"))

	// Header: logo (or the shop name) left, the shop's name and address right.
	y := margin
	headerBottom := y
	if logo >= 0 {
		iw, ih := p.ImageSize(logo)
		maxW, maxH := 200.0, 70.0
		scale := math.Min(maxW/float64(iw), maxH/float64(ih))
		if scale > 1 {
			scale = 1
		}
		dw, dh := float64(iw)*scale, float64(ih)*scale
		p.Image(logo, margin, y, dw, dh)
		headerBottom = y + dh
	} else {
		p.Text(margin, y+18, 20, true, shopName)
		headerBottom = y + 24
	}
	ry := y + 10
	p.TextRight(right, ry, 10, true, shopName)
	ry += 13
	for _, line := range strings.Split(strings.ReplaceAll(s.gooExtString(gooPDFKey, "shop_address"), "\r\n", "\n"), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		p.TextRight(right, ry, 9, false, strings.TrimSpace(line))
		ry += 12
	}
	y = math.Max(headerBottom, ry) + 24

	title := "INVOICE"
	if !invoice {
		title = "PACKING SLIP"
	}
	p.Text(margin, y, 18, true, title)
	y += 26

	// Addresses and the document data.
	colW := (p.W - 2*margin) / 3
	ay := y
	writeBlock := func(x float64, heading string, lines []string) float64 {
		yy := ay
		if heading != "" {
			p.Text(x, yy, 9, true, heading)
			yy += 13
		}
		for _, l := range lines {
			for _, wl := range gooPDFWrap(l, 9, false, colW-10) {
				p.Text(x, yy, 9, false, wl)
				yy += 12
			}
		}
		return yy
	}
	billing := gooPDFAddress(o.Billing)
	if s.gooExtBool(gooPDFKey, "display_email") && o.Billing["email"] != "" {
		billing = append(billing, o.Billing["email"])
	}
	if s.gooExtBool(gooPDFKey, "display_phone") && o.Billing["phone"] != "" {
		billing = append(billing, o.Billing["phone"])
	}
	shipping := gooPDFAddress(o.Shipping)
	var bottoms []float64
	if invoice {
		bottoms = append(bottoms, writeBlock(margin, "Billing address:", billing))
		if s.gooExtBool(gooPDFKey, "display_shipping_address") && len(shipping) > 0 {
			bottoms = append(bottoms, writeBlock(margin+colW, "Ship to:", shipping))
		}
	} else {
		if len(shipping) == 0 {
			shipping = gooPDFAddress(o.Billing)
		}
		if s.gooExtBool(gooPDFKey, "display_phone") && (o.Shipping["phone"] != "" || o.Billing["phone"] != "") {
			shipping = append(shipping, defaultStr(o.Shipping["phone"], o.Billing["phone"]))
		}
		bottoms = append(bottoms, writeBlock(margin, "Shipping address:", shipping))
		if len(o.Shipping) > 0 {
			bottoms = append(bottoms, writeBlock(margin+colW, "Billing address:", gooPDFAddress(o.Billing)))
		}
	}
	// Document data, right column.
	type kv struct{ k, v string }
	var data []kv
	dateFmt := defaultStr(s.settings.String("date_format"), "F j, Y")
	if invoice {
		data = append(data, kv{"Invoice Number:", o.MetaString("_wcpdf_invoice_number")}, kv{"Invoice Date:", wp.FormatDate(gooPDFInvoiceDate(o), dateFmt)})
	}
	data = append(data, kv{"Order Number:", o.Number()}, kv{"Order Date:", wp.FormatDate(o.DateCreated, dateFmt)})
	if invoice {
		if o.PaymentMethodTitle != "" {
			data = append(data, kv{"Payment Method:", o.PaymentMethodTitle})
		}
	} else {
		var methods []string
		for _, it := range o.ItemsOf("shipping") {
			methods = append(methods, html.UnescapeString(it.Name))
		}
		if len(methods) > 0 {
			data = append(data, kv{"Shipping Method:", strings.Join(methods, ", ")})
		}
	}
	dy := ay
	dx := margin + 2*colW
	for _, d := range data {
		p.Text(dx, dy, 9, true, d.k)
		for _, wl := range gooPDFWrap(d.v, 9, false, colW-82) {
			p.Text(dx+82, dy, 9, false, wl)
			dy += 12
		}
	}
	bottoms = append(bottoms, dy)
	for _, b := range bottoms {
		y = math.Max(y, b)
	}
	y += 22

	// Items table.
	bottomLimit := p.H - margin - 50
	type col struct {
		title string
		w     float64
		right bool
	}
	tableW := p.W - 2*margin
	cols := []col{{"Product", tableW - 260, false}, {"SKU", 90, false}, {"Quantity", 50, true}, {"Price", 60, true}, {"Total", 60, true}}
	if !invoice {
		cols = []col{{"Product", tableW - 200, false}, {"SKU", 110, false}, {"Weight", 40, true}, {"Quantity", 50, true}}
	}
	header := func() {
		p.Rect(margin, y-12, tableW, 18, 0.15)
		p.SetGray(1)
		x := margin + 6
		for _, c := range cols {
			if c.right {
				p.TextRight(x+c.w-12, y, 9, true, c.title)
			} else {
				p.Text(x, y, 9, true, c.title)
			}
			x += c.w
		}
		p.SetGray(0)
		y += 20
	}
	newPage := func() {
		p.AddPage()
		y = margin + 12
		header()
	}
	header()
	incl := s.gooOptString("tax_display_cart") == "incl"
	wu := defaultStr(s.gooOptString("weight_unit"), "kg")
	for _, it := range o.ItemsOf("line_item") {
		sku, weight := "", ""
		pid := it.ProductID
		if it.VariationID != 0 {
			pid = it.VariationID
		}
		if prod, err := s.gooGetProduct(ctx, pid); err == nil {
			sku = prod.SKU
			if sku == "" && prod.Type == gooTypeVariation {
				if parent := s.gooParent(ctx, prod); parent != nil {
					sku = parent.SKU
				}
			}
			if w := s.gooWeightOf(ctx, prod); w > 0 {
				weight = strconv.FormatFloat(w*it.Quantity, 'f', -1, 64) + " " + wu
			}
		}
		name := html.UnescapeString(wp.StripTags(it.Name))
		nameLines := gooPDFWrap(name, 9, false, cols[0].w-14)
		// Item meta (variation attributes, add-ons) in small type.
		var metaLines []string
		if disp, ok := it.Meta["_display"].([]any); ok {
			for _, d := range disp {
				if m, ok := d.(map[string]any); ok {
					k, _ := m["key"].(string)
					v, _ := m["value"].(string)
					metaLines = append(metaLines, gooPDFWrap(html.UnescapeString(wp.StripTags(k+": "+v)), 7.5, false, cols[0].w-14)...)
				}
			}
		}
		rowH := float64(len(nameLines))*11 + float64(len(metaLines))*9.5 + 8
		if y+rowH > bottomLimit {
			newPage()
		}
		x := margin + 6
		ly := y
		for _, l := range nameLines {
			p.Text(x, ly, 9, false, l)
			ly += 11
		}
		p.SetGray(0.35)
		for _, l := range metaLines {
			p.Text(x, ly, 7.5, false, l)
			ly += 9.5
		}
		p.SetGray(0)
		x += cols[0].w
		p.Text(x, y, 9, false, sku)
		x += cols[1].w
		if invoice {
			qty := it.Quantity
			line := it.Subtotal
			total := it.Total
			if incl {
				line += it.SubtotalTax
				total += it.TotalTax
			}
			unit := 0.0
			if qty != 0 {
				unit = line / qty
			}
			p.TextRight(x+cols[2].w-12, y, 9, false, strconv.FormatFloat(qty, 'f', -1, 64))
			x += cols[2].w
			p.TextRight(x+cols[3].w-12, y, 9, false, money(unit))
			x += cols[3].w
			p.TextRight(x+cols[4].w-12, y, 9, false, money(line))
			if math.Abs(line-total) > 0.004 {
				p.SetGray(0.35)
				p.TextRight(x+cols[4].w-12, y+10, 7.5, false, money(total)+" after discount")
				p.SetGray(0)
			}
		} else {
			p.TextRight(x+cols[2].w-12, y, 9, false, weight)
			x += cols[2].w
			p.TextRight(x+cols[3].w-12, y, 9, true, strconv.FormatFloat(it.Quantity, 'f', -1, 64))
		}
		y += rowH
		p.Line(margin, y-10, right, y-10, 0.5, 0.8)
	}

	// Totals (invoice).
	if invoice {
		type row struct {
			label, value string
			bold         bool
		}
		var rows []row
		sub := o.Subtotal()
		if incl {
			for _, it := range o.ItemsOf("line_item") {
				sub += it.SubtotalTax
			}
		}
		rows = append(rows, row{"Subtotal", money(sub), false})
		if o.DiscountTotal > 0 {
			d := o.DiscountTotal
			if incl {
				d += o.DiscountTax
			}
			var codes []string
			for _, cp := range o.ItemsOf("coupon") {
				codes = append(codes, cp.Name)
			}
			label := "Discount"
			if len(codes) > 0 {
				label += " (" + strings.Join(codes, ", ") + ")"
			}
			rows = append(rows, row{label, "-" + money(d), false})
		}
		if ships := o.ItemsOf("shipping"); len(ships) > 0 {
			var names []string
			for _, it := range ships {
				names = append(names, html.UnescapeString(it.Name))
			}
			st := o.ShippingTotal
			if incl {
				st += o.ShippingTax
			}
			v := money(st)
			if st == 0 {
				v = "Free"
			}
			rows = append(rows, row{"Shipping (" + strings.Join(names, ", ") + ")", v, false})
		}
		for _, f := range o.ItemsOf("fee") {
			v := f.Total
			if incl {
				v += f.TotalTax
			}
			rows = append(rows, row{html.UnescapeString(f.Name), money(v), false})
		}
		if s.gooTaxEnabled() || o.TotalTax > 0 {
			if !incl {
				for _, t := range o.ItemsOf("tax") {
					amt := gooPDFMetaFloat(t.Meta["tax_amount"]) + gooPDFMetaFloat(t.Meta["shipping_tax_amount"])
					label := defaultStr(t.MetaString("label"), t.Name)
					rows = append(rows, row{label, money(amt), false})
				}
			}
		}
		total := money(o.Total)
		if incl && o.TotalTax > 0 {
			total += " (includes " + money(o.TotalTax) + " tax)"
		}
		rows = append(rows, row{"Total", total, true})
		if refunds, _ := s.gooRefunds(ctx, o.ID); len(refunds) > 0 {
			var refunded float64
			for _, r := range refunds {
				refunded += math.Abs(r.Total)
				rows = append(rows, row{"Refund", "-" + money(math.Abs(r.Total)), false})
			}
			rows = append(rows, row{"Net total", money(o.Total - refunded), true})
		}
		y += 4
		if y+float64(len(rows))*16+10 > bottomLimit {
			p.AddPage()
			y = margin + 12
		}
		lx := right - 250
		for _, r := range rows {
			if r.bold {
				p.Line(lx, y-11, right, y-11, 0.8, 0.2)
			}
			for i, l := range gooPDFWrap(r.label, 9, r.bold, 140) {
				p.Text(lx, y+float64(i)*11, 9, r.bold, l)
			}
			p.TextRight(right-6, y, 9, r.bold, r.value)
			y += 16 + float64(len(gooPDFWrap(r.label, 9, r.bold, 140))-1)*11
		}
	}

	// Customer note.
	if note := strings.TrimSpace(o.CustomerNote); note != "" {
		lines := gooPDFWrap(html.UnescapeString(wp.StripTags(note)), 9, false, p.W-2*margin)
		if y+20+float64(len(lines))*12 > bottomLimit {
			p.AddPage()
			y = margin + 12
		}
		y += 12
		p.Text(margin, y, 9, true, "Customer note:")
		y += 13
		for _, l := range lines {
			p.Text(margin, y, 9, false, l)
			y += 12
		}
	}

	// Footer and page numbers on each page of this document.
	footer := strings.TrimSpace(s.gooExtString(gooPDFKey, "footer"))
	n := p.PageCount() - firstPage
	for i := firstPage; i < p.PageCount(); i++ {
		fy := p.H - margin + 6
		if footer != "" {
			lines := gooPDFWrap(html.UnescapeString(wp.StripTags(footer)), 7.5, false, p.W-2*margin)
			if len(lines) > 3 {
				lines = lines[:3]
			}
			p.SetGray(0.3)
			for j := len(lines) - 1; j >= 0; j-- {
				p.TextCenterOn(i, p.W/2, fy-float64(len(lines)-1-j)*9.5-12, 7.5, false, lines[j])
			}
			p.SetGray(0)
		}
		if n > 1 {
			p.SetGray(0.3)
			p.TextCenterOn(i, p.W/2, fy, 7.5, false, "Page "+strconv.Itoa(i-firstPage+1)+" of "+strconv.Itoa(n))
			p.SetGray(0)
		}
	}
}

func gooPDFMetaFloat(v any) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case string:
		f, _ := strconv.ParseFloat(x, 64)
		return f
	}
	return 0
}

// gooPDFFileName is the download name of a document.
func gooPDFFileName(doc string, orders []*gooOrder) string {
	if len(orders) != 1 {
		return doc + "s-" + time.Now().Format("20060102-150405") + ".pdf"
	}
	o := orders[0]
	if doc == "invoice" {
		n := gooSanitizeKey(o.MetaString("_wcpdf_invoice_number"))
		if n == "" {
			n = o.Number()
		}
		return "invoice-" + n + ".pdf"
	}
	return "packing-slip-" + o.Number() + ".pdf"
}

func gooPDFStream(c *gin.Context, data []byte, name string, inline bool) {
	disp := "attachment"
	if inline {
		disp = "inline"
	}
	c.Header("Content-Disposition", disp+`; filename="`+name+`"`)
	c.Header("Cache-Control", "private, no-store")
	c.Header("X-Robots-Tag", "noindex, nofollow")
	c.Data(http.StatusOK, "application/pdf", data)
}

// Admin --------------------------------------------------------------------------------------------------

// gooPDFAdmin is Goocommerce › PDF documents: with ?document=invoice|packing-slip&order_id= (or
// order_ids[]) it streams the PDF; else it lists recent orders with their documents and a bulk export.
func (s *Server) gooPDFAdmin(c *gin.Context) {
	ctx := c.Request.Context()
	u := currentUser(c)
	if !u.Can("edit_shop_orders", nil) {
		c.String(http.StatusForbidden, "Sorry, you are not allowed to access this page.")
		return
	}
	if doc := c.Query("document"); doc != "" {
		if !s.checkNonce(c, gooPDFNonce) {
			s.denyNonce(c)
			return
		}
		if doc != "invoice" && doc != "packing-slip" {
			c.String(http.StatusBadRequest, "Unknown document type.")
			return
		}
		var ids []int64
		for _, v := range append(c.QueryArray("order_ids[]"), strings.Split(c.Query("order_id"), ",")...) {
			if id, err := strconv.ParseInt(strings.TrimSpace(v), 10, 64); err == nil && id > 0 && !gooInt64In(id, ids) {
				ids = append(ids, id)
			}
		}
		if len(ids) == 0 || len(ids) > 200 {
			c.String(http.StatusBadRequest, "Choose between 1 and 200 orders.")
			return
		}
		var orders []*gooOrder
		for _, id := range ids {
			if o, err := s.gooGetOrder(ctx, id); err == nil && o.Type == "shop_order" {
				orders = append(orders, o)
			}
		}
		if len(orders) == 0 {
			c.String(http.StatusNotFound, "Order not found.")
			return
		}
		data, err := s.gooPDFRender(ctx, doc, orders)
		if err != nil {
			c.String(http.StatusUnprocessableEntity, err.Error())
			return
		}
		if doc == "invoice" {
			for _, o := range orders {
				s.gooPDFMarkPrinted(ctx, o, "download")
			}
		}
		gooPDFStream(c, data, gooPDFFileName(doc, orders), true)
		return
	}
	orders, total, _ := s.gooQueryOrders(ctx, gooOrderQuery{OrderBy: "date", Order: "DESC", Page: 1, PerPage: 30})
	nonce := s.nonce(c, gooPDFNonce)
	type row struct {
		ID                         int64
		Number, Customer, Status   string
		Date                       string
		Total                      template.HTML
		Invoice, Printed           string
		InvoiceURL, PackingSlipURL string
	}
	var rows []row
	for _, o := range orders {
		r := row{ID: o.ID, Number: o.Number(), Customer: defaultStr(o.BillingName(), o.Billing["email"]), Status: gooStatusLabel(o.Status),
			Date: o.DateCreated.Format("2006-01-02"), Total: s.gooPriceIn(o.Total, o.Currency), Invoice: o.MetaString("_wcpdf_invoice_number"),
			Printed:        o.MetaString("_wcpdf_invoice_printed_on"),
			InvoiceURL:     "/wp-admin/goocommerce?page=pdf-documents&document=invoice&order_id=" + itoa64(o.ID) + "&_wpnonce=" + nonce,
			PackingSlipURL: "/wp-admin/goocommerce?page=pdf-documents&document=packing-slip&order_id=" + itoa64(o.ID) + "&_wpnonce=" + nonce}
		if s.gooPDFFree(o) {
			r.InvoiceURL = ""
		}
		rows = append(rows, r)
	}
	var next, applied int64
	_ = s.store.Pool.QueryRow(ctx, `SELECT next, applied FROM goo_pdf_counters WHERE name = 'invoice'`).Scan(&next, &applied)
	if setting := int64(s.gooExtInt(gooPDFKey, "next_number")); next == 0 || applied != max(setting, 1) {
		next = max(setting, 1)
	}
	s.adminPage(c, "goocommerce?page=pdf-documents", "PDF documents", "goocommerce_page_goo-pdf-documents", "admin/goo-ext-pdf",
		map[string]any{"Rows": rows, "Total": total, "Nonce": nonce, "Next": s.gooPDFFormatNumber(next, &gooOrder{DateCreated: time.Now()}, time.Now()),
			"On": s.gooExtOn(gooPDFKey)}, gooFlash(c)...)
}

// Customers -----------------------------------------------------------------------------------------------

// gooInvoiceLink is the customer's invoice download link (owner or order key), for My Account orders
// and e-mails; "" when the customer cannot download it.
func (s *Server) gooInvoiceLink(o *gooOrder) string {
	if o == nil || !s.gooPDFCustomerMay(o) {
		return ""
	}
	return s.links(context.Background()).HomeURL("/?goo-pdf=invoice&order_id=" + itoa64(o.ID) + "&key=" + url.QueryEscape(o.OrderKey))
}

// gooPDFCustomerMay applies "Allow customers to download" and "Disable for free orders".
func (s *Server) gooPDFCustomerMay(o *gooOrder) bool {
	if !s.gooExtOn(gooPDFKey) || o.Type != "shop_order" || s.gooPDFFree(o) {
		return false
	}
	switch s.gooExtString(gooPDFKey, "my_account_access") {
	case "never":
		return false
	case "available":
		return o.MetaString("_wcpdf_invoice_number") != ""
	}
	return o.Status != "checkout-draft" && o.Status != "trash"
}

// gooPDFRoute serves /?goo-pdf=invoice&order_id=&key= to the order's customer (or whoever has its key).
func gooPDFRoute(s *Server, c *gin.Context, path string) bool {
	doc := c.Query("goo-pdf")
	if doc == "" || !s.gooExtOn(gooPDFKey) {
		return false
	}
	ctx := c.Request.Context()
	deny := func(code int, msg string) bool {
		c.Header("X-Robots-Tag", "noindex")
		c.String(code, msg)
		return true
	}
	if doc != "invoice" {
		return deny(http.StatusNotFound, "This document is not available.")
	}
	id, _ := strconv.ParseInt(c.Query("order_id"), 10, 64)
	o, err := s.gooGetOrder(ctx, id)
	if err != nil || o.Type != "shop_order" {
		return deny(http.StatusNotFound, "Invalid order.")
	}
	owner := false
	if u := currentUser(c); u != nil && o.CustomerID != 0 && u.ID == o.CustomerID {
		owner = true
	}
	if key := c.Query("key"); !owner && (key == "" || subtle.ConstantTimeCompare([]byte(key), []byte(o.OrderKey)) != 1) {
		return deny(http.StatusForbidden, "You do not have sufficient permissions to access this page.")
	}
	if !s.gooPDFCustomerMay(o) {
		return deny(http.StatusNotFound, "This document is not available.")
	}
	data, err := s.gooPDFRender(ctx, "invoice", []*gooOrder{o})
	if err != nil {
		return deny(http.StatusNotFound, err.Error())
	}
	gooPDFStream(c, data, gooPDFFileName("invoice", []*gooOrder{o}), false)
	return true
}

// gooPDFThankYou links the invoice on the order received page (?key=<order key>).
func gooPDFThankYou(s *Server, c *gin.Context) template.HTML {
	if !s.gooExtOn(gooPDFKey) {
		return ""
	}
	key := c.Query("key")
	if key == "" {
		return ""
	}
	o, err := s.gooOrderByKey(c.Request.Context(), key)
	if err != nil {
		return ""
	}
	link := s.gooInvoiceLink(o)
	if link == "" {
		return ""
	}
	return template.HTML(`<p class="goo-pdf-invoice-link"><a class="button" href="` + gooEsc(link) + `">Download invoice (PDF)</a></p>`)
}

// gooPDFEmailAttach attaches the invoice to the e-mails chosen in the settings.
func gooPDFEmailAttach(s *Server, ctx context.Context, emailID string, o *gooOrder) map[string][]byte {
	if !s.gooExtOn(gooPDFKey) || o == nil || o.Type != "shop_order" || s.gooPDFFree(o) {
		return nil
	}
	if !containsStr(gooXCStringList(s.gooExtSettings(gooPDFKey)["attach_to"]), emailID) {
		return nil
	}
	data, err := s.gooPDFRender(ctx, "invoice", []*gooOrder{o})
	if err != nil {
		return nil
	}
	s.gooPDFMarkPrinted(ctx, o, "email")
	return map[string][]byte{gooPDFFileName("invoice", []*gooOrder{o}): data}
}
